fn usage() -> ! {
    eprintln!(
        "yoyo —YOYO verifier (Rust DDC peer)\n\n\
         Usage:\n\
           yoyo link [--target=win32|linux|stub|baremetal|cuda|android|apple|8051|x86|freedos|riscv64|mips|ppc64le|avr|arm32|wasm|macos-x64|serenity|loongarch|sparc|riscv32|arm64-win] [--posture=...] [--morph=...] <input.ty> <output>\n\
           yoyo diff <a.bin> <b.bin>\n\
           yoyo hash <file>\n\
           yoyo selftest\n\
           yoyo render <input.ty>\n\
           yoyo test golden\n\n\
         Note: --posture= / --morph= are recognized and fail-closed (NON-CONFORMING)\n\
         until posture/morph backends land (PROMPT Part E.19 / E.16).\n\
          `test golden` currently runs G00鈥揋05 plus scoped G-SM, G-SM-CHAIN鈥-SM-CHAIN12, G-SM-INC, G-SM-DEC, G-SM-ADD-IMM, G-SM-SUB-IMM, G-SM-MOVRR, G-SM-ORV, G-SM-NOP, G-SM-RAW-BYTES, G-SM-IMUL, G-SM-SUBV, G-SM-CMP, G-SM-LDB-BODY, G-SM-SET-CONTROL, G-SM-GET, G-SM-LDB-OFF8-HANDLER, G-SM-LDB-OFF127-HANDLER, G-SM-LDB-OFFM128-HANDLER, G-SM-LDB-OFF64-HANDLER, G-SM-LDB-OFF16-HANDLER, G-SM-LDB-OFF32-HANDLER, G-SM-LDB-OFF96-HANDLER, G-SM-LDB-OFF112-HANDLER, G-SM-ADDV-SWAP, G-SM-ORV-SWAP, G-SM-SUBV-SWAP, G-SM-GET-ALT, G-SM-ADDV-H52, G-SM-SET-LARGE, G-SM-ORV-H52, G-SM-SUBV-H52, G-SM-IMUL-SWAP, G-SM-IMUL-H52, G-SM-CMP-SWAP, G-SM-GET-H52, G-SM-SET-DEADBEEF, G-SM-LDB-DST51, G-SM-JMP, G-SM-CALL, G-SM-JE, G-SM-JCC-ALL, and G-SM-IO (not full Appendix F).\n"
    );
    std::process::exit(2);
}

fn main() -> ExitCode {
    let mut args: Vec<String> = env::args().skip(1).collect();
    if args.is_empty() {
        usage();
    }

    let mut budget = Budget::new(BUDGET_PHASE1);
    // Parse --budget=
    args.retain(|a| {
        if let Some(v) = a.strip_prefix("--budget=") {
            if let Ok(n) = v.parse::<u64>() {
                budget = Budget::new(n);
            }
            false
        } else {
            true
        }
    });

    let cmd = args[0].as_str();
    let result = match cmd {
        "link" => cmd_link(&args[1..], &budget),
        "diff" => cmd_diff(&args[1..]),
        "hash" => cmd_hash(&args[1..]),
        "selftest" => {
            self_test::run_self_test().map(|_| {
                println!("selftest: ok");
            })
        }
        "render" => cmd_render(&args[1..]),
        "test" => cmd_test(&args[1..]),
        _ => {
            eprintln!("unknown command '{cmd}'");
            usage();
        }
    };

    match result {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            eprintln!("error: {e}");
            ExitCode::FAILURE
        }
    }
}

fn cmd_link(args: &[String], budget: &Budget) -> Result<(), types::IsaError> {
    let mut target = PlatformKind::Win32;
    let mut rest = Vec::new();
    let mut selfhost = false;
    for a in args {
        if let Some(t) = a.strip_prefix("--target=") {
            target = parse_platform(t)?;
        } else if let Some(p) = a.strip_prefix("--posture=") {
            // Fail-closed: aliases are recognized (Part E.19.5) but backends are NON-CONFORMING.
            let ok_alias = matches!(p, "energy-extreme" | "perf-extreme" | "auto")
                || p.starts_with("blend:");
            if !ok_alias {
                return Err(types::IsaError::IoError {
                    msg: format!(
                        "unknown --posture={p} (want energy-extreme|perf-extreme|blend:<w>|auto)"
                    ),
                });
            }
            return Err(types::IsaError::IoError {
                msg: format!(
                    "[NON-CONFORMING] --posture={p} recognized but posture backends not implemented; M-posture stays red (PROMPT 搂E.19)"
                ),
            });
        } else if let Some(m) = a.strip_prefix("--morph=") {
            if m.is_empty() {
                return Err(types::IsaError::IoError {
                    msg: "empty --morph= id".into(),
                });
            }
            return Err(types::IsaError::IoError {
                msg: format!(
                    "[NON-CONFORMING] --morph={m} recognized but morph backends not implemented; M-morph stays red (PROMPT Part E)"
                ),
            });
        } else if a == "--selfhost" {
            selfhost = true;
        } else {
            rest.push(a.clone());
        }
    }
    if rest.len() != 2 {
        usage();
    }
    budget.consume(1)?;
    let input_path = &rest[0];
    let input_ext = std::path::Path::new(input_path)
        .extension()
        .and_then(|e| e.to_str())
        .unwrap_or("");

    // CUDA uses a separate TIR→PTX path (not x64 emit).
    // Wasm uses a separate TIR→Wasm-binary path (not x64 emit).
    if target == PlatformKind::Cuda {
        let tir = if input_ext == "tyb" || {
            let data = std::fs::read(input_path).ok();
            data.as_ref().map_or(false, |d| tyb_parser::is_tyb(d))
        } {
            let data = std::fs::read(input_path).map_err(|e| types::IsaError::IoError {
                msg: e.to_string(),
            })?;
            executor::compile_tyb_source_to_tir(&data)?
        } else {
            let src = fs::read_to_string(input_path).map_err(|e| types::IsaError::IoError {
                msg: e.to_string(),
            })?;
            executor::compile_ty_source_to_tir(&src)?
        };
        let ptx = cuda_backend::emit_cuda(&tir)?;
        println!(
            "emit: {} ops → PTX ({} lines), entry H_{:02X}",
            tir.len(),
            ptx.lines().count(),
            tir.iter()
                .find(|i| matches!(i.op, crate::tir::TirOp::Handler))
                .and_then(|i| i.args.first().copied())
                .unwrap_or(0)
        );
        fs::write(&rest[1], &ptx).map_err(|e| types::IsaError::IoError {
            msg: e.to_string(),
        })?;
        println!("wrote PTX {} ({} bytes)", rest[1], ptx.len());
        return Ok(());
    }

    if target == PlatformKind::Wasm {
        let tir = if input_ext == "tyb" || {
            let data = std::fs::read(input_path).ok();
            data.as_ref().map_or(false, |d| tyb_parser::is_tyb(d))
        } {
            let data = std::fs::read(input_path).map_err(|e| types::IsaError::IoError {
                msg: e.to_string(),
            })?;
            executor::compile_tyb_source_to_tir(&data)?
        } else {
            let src = fs::read_to_string(input_path).map_err(|e| types::IsaError::IoError {
                msg: e.to_string(),
            })?;
            executor::compile_ty_source_to_tir(&src)?
        };
        let wasm = wasm_backend::emit_wasm(&tir)?;
        println!(
            "emit: {} ops → Wasm ({} bytes), entry H_{:02X}",
            tir.len(),
            wasm.len(),
            tir.iter()
                .find(|i| matches!(i.op, crate::tir::TirOp::Handler))
                .and_then(|i| i.args.first().copied())
                .unwrap_or(0)
        );
        fs::write(&rest[1], &wasm).map_err(|e| types::IsaError::IoError {
            msg: e.to_string(),
        })?;
        println!("wrote Wasm {} ({} bytes)", rest[1], wasm.len());
        return Ok(());
    }

    // SerenityOS uses x64 emit but writes SERE flat binary.
    if target == PlatformKind::Serenity {
        let out = if input_ext == "tyb" || {
            let data = std::fs::read(input_path).ok();
            data.as_ref().map_or(false, |d| tyb_parser::is_tyb(d))
        } {
            let data = std::fs::read(input_path).map_err(|e| types::IsaError::IoError {
                msg: e.to_string(),
            })?;
            executor::compile_tyb_source(&data, target)?
        } else {
            let src = fs::read_to_string(input_path).map_err(|e| types::IsaError::IoError {
                msg: e.to_string(),
            })?;
            executor::compile_ty_source(&src, target)?
        };
        let mut img = Vec::new();
        img.extend_from_slice(b"SERE");
        img.extend_from_slice(&8u32.to_le_bytes());
        img.extend_from_slice(&out.code);
        fs::write(&rest[1], &img).map_err(|e| types::IsaError::IoError {
            msg: e.to_string(),
        })?;
        println!("wrote Serenity flat {} ({} bytes)", rest[1], img.len());
        return Ok(());
    }

    let out = if input_ext == "tyb" || {
        let data = std::fs::read(input_path).ok();
        data.as_ref().map_or(false, |d| tyb_parser::is_tyb(d))
    } {
        let data = std::fs::read(input_path).map_err(|e| types::IsaError::IoError {
            msg: e.to_string(),
        })?;
        executor::compile_tyb_source(&data, target)?
    } else {
        let src = fs::read_to_string(input_path).map_err(|e| types::IsaError::IoError {
            msg: e.to_string(),
        })?;
        executor::compile_ty_source(&src, target)?
    };
    let op_count = std::fs::read_to_string(input_path)
        .ok()
        .map(|s| s.lines().filter(|l| !l.trim().is_empty() && !l.trim().starts_with(';')).count())
        .unwrap_or(0);
    println!(
        "emit: {} ops → {} code bytes, {} data bytes, entry H_{:02X}",
        op_count,
        out.code.len(),
        out.data.len(),
        out.entry_hh
    );

    match target {
        PlatformKind::Win32 => {
            let pe = if selfhost {
                let hot = selfhost::build_hot(&out.handler_offsets);
                let startup = selfhost::gen_selfhost_startup(0, 0, 0);
                pe_link::link_pe_selfhost(&out.code, &out.data, &hot, &startup)?
            } else {
                pe_link::link_pe(&out.code, &out.data)?
            };
            fs::write(&rest[1], &pe.bytes).map_err(|e| types::IsaError::IoError {
                msg: e.to_string(),
            })?;
            println!("wrote PE32+ {} ({} bytes)", rest[1], pe.bytes.len());
        }
        PlatformKind::Linux => {
            let elf = elf_link::link_elf(&out.code, &out.data)?;
            fs::write(&rest[1], &elf.bytes).map_err(|e| types::IsaError::IoError {
                msg: e.to_string(),
            })?;
            println!("wrote ELF64 {} ({} bytes)", rest[1], elf.bytes.len());
        }
        PlatformKind::Stub | PlatformKind::BareMetal => {
            // Flat code dump for non-PE/non-ELF targets
            let mut blob = Vec::new();
            blob.extend_from_slice(startup::startup_blob_baremetal());
            blob.extend_from_slice(&out.code);
            fs::write(&rest[1], &blob).map_err(|e| types::IsaError::IoError {
                msg: e.to_string(),
            })?;
            println!("wrote flat {} ({} bytes)", rest[1], blob.len());
        }
        PlatformKind::Cuda => {
            unreachable!("CUDA handled above before x64 emit pipeline");
        }
        PlatformKind::Android => {
            let elf = arm64_elf_link::link_arm64_elf(&out.code, &out.data)?;
            fs::write(&rest[1], &elf.bytes).map_err(|e| types::IsaError::IoError {
                msg: e.to_string(),
            })?;
            println!("wrote ARM64 ELF64 {} ({} bytes)", rest[1], elf.bytes.len());
        }
        PlatformKind::Apple => {
            let mach = apple_backend::link_macho64(&out.code, &out.data)?;
            fs::write(&rest[1], &mach.bytes).map_err(|e| types::IsaError::IoError {
                msg: e.to_string(),
            })?;
            println!("wrote Mach-O64 {} ({} bytes)", rest[1], mach.bytes.len());
        }
        PlatformKind::Eight051 => {
            // 8051 produces a flat binary — no linker wrapper needed.
            fs::write(&rest[1], &out.code).map_err(|e| types::IsaError::IoError {
                msg: e.to_string(),
            })?;
            println!("wrote 8051 flat {} ({} bytes)", rest[1], out.code.len());
        }
        PlatformKind::X86 => {
            let pe = x86_link::link_x86(&out.code, &out.data)?;
            fs::write(&rest[1], &pe.bytes).map_err(|e| types::IsaError::IoError {
                msg: e.to_string(),
            })?;
            println!("wrote PE32 {} ({} bytes)", rest[1], pe.bytes.len());
        }
        PlatformKind::Freedos => {
            // DOS COM: flat binary — no header, code runs at 0x0000:0x0100.
            fs::write(&rest[1], &out.code).map_err(|e| types::IsaError::IoError {
                msg: e.to_string(),
            })?;
            println!("wrote DOS COM {} ({} bytes)", rest[1], out.code.len());
        }
        PlatformKind::Riscv64 => {
            let elf = riscv_elf_link::link_riscv_elf(&out.code, &out.data)?;
            fs::write(&rest[1], &elf.bytes).map_err(|e| types::IsaError::IoError {
                msg: e.to_string(),
            })?;
            println!("wrote RISC-V ELF64 {} ({} bytes)", rest[1], elf.bytes.len());
        }
        PlatformKind::Mips => {
            let elf = mips_elf_link::link_mips_elf(&out.code, &out.data)?;
            fs::write(&rest[1], &elf.bytes).map_err(|e| types::IsaError::IoError {
                msg: e.to_string(),
            })?;
            println!("wrote MIPS ELF32BE {} ({} bytes)", rest[1], elf.bytes.len());
        }
        PlatformKind::PowerPc64Le => {
            let elf = ppc_elf_link::link_ppc_elf(&out.code, &out.data)?;
            fs::write(&rest[1], &elf.bytes).map_err(|e| types::IsaError::IoError {
                msg: e.to_string(),
            })?;
            println!("wrote PPC64LE ELF64 {} ({} bytes)", rest[1], elf.bytes.len());
        }
        PlatformKind::Avr => {
            fs::write(&rest[1], &out.code).map_err(|e| types::IsaError::IoError {
                msg: e.to_string(),
            })?;
            println!("wrote AVR flat {} ({} bytes)", rest[1], out.code.len());
        }
        PlatformKind::Arm32 => {
            let elf = arm32_elf_link::link_arm32_elf(&out.code, &out.data)?;
            fs::write(&rest[1], &elf.bytes).map_err(|e| types::IsaError::IoError {
                msg: e.to_string(),
            })?;
            println!("wrote ARM32 ELF32 {} ({} bytes)", rest[1], elf.bytes.len());
        }
        PlatformKind::MachoX64 => {
            let mach = macho_x64_link::link_macho_x64(&out.code, &out.data)?;
            fs::write(&rest[1], &mach.bytes).map_err(|e| types::IsaError::IoError {
                msg: e.to_string(),
            })?;
            println!("wrote Mach-O64 x64 {} ({} bytes)", rest[1], mach.bytes.len());
        }
        PlatformKind::Wasm | PlatformKind::Serenity => {
            unreachable!("Wasm and Serenity handled above before generic emit")
        }
        PlatformKind::LoongArch => {
            let elf = loongarch_elf_link::link_loongarch_elf(&out.code, &out.data)?;
            fs::write(&rest[1], &elf.bytes).map_err(|e| types::IsaError::IoError {
                msg: e.to_string(),
            })?;
            println!("wrote LoongArch ELF64 {} ({} bytes)", rest[1], elf.bytes.len());
        }
        PlatformKind::Sparc => {
            let elf = sparc_elf_link::link_sparc_elf(&out.code, &out.data)?;
            fs::write(&rest[1], &elf.bytes).map_err(|e| types::IsaError::IoError {
                msg: e.to_string(),
            })?;
            println!("wrote SPARC ELF32BE {} ({} bytes)", rest[1], elf.bytes.len());
        }
        PlatformKind::Riscv32 => {
            let elf = riscv32_elf_link::link_riscv32_elf(&out.code, &out.data)?;
            fs::write(&rest[1], &elf.bytes).map_err(|e| types::IsaError::IoError {
                msg: e.to_string(),
            })?;
            println!("wrote RV32 ELF32 {} ({} bytes)", rest[1], elf.bytes.len());
        }
        PlatformKind::Aarch64Windows => {
            let pe = arm64_pe_link::link_arm64_pe(&out.code, &out.data)?;
            fs::write(&rest[1], &pe.bytes).map_err(|e| types::IsaError::IoError {
                msg: e.to_string(),
            })?;
            println!("wrote ARM64 PE32+ {} ({} bytes)", rest[1], pe.bytes.len());
        }
    }
    Ok(())
}

fn cmd_diff(args: &[String]) -> Result<(), types::IsaError> {
    if args.len() != 2 {
        usage();
    }
    let a = fs::read(&args[0]).map_err(|e| types::IsaError::IoError { msg: e.to_string() })?;
    let b = fs::read(&args[1]).map_err(|e| types::IsaError::IoError { msg: e.to_string() })?;
    let report = ddc::compare_pe_text(&a, &b)?;
    println!("compared_bytes: {}", report.compared_bytes);
    println!("hash_a: {}", report.hash_a);
    println!("hash_b: {}", report.hash_b);
    if report.equal {
        println!("DDC: EQUAL");
        Ok(())
    } else {
        println!("DDC: DIFFER");
        Err(types::IsaError::ParseError {
            line: 0,
            msg: "DDC mismatch".into(),
        })
    }
}

fn cmd_hash(args: &[String]) -> Result<(), types::IsaError> {
    if args.len() != 1 {
        usage();
    }
    let data = fs::read(&args[0]).map_err(|e| types::IsaError::IoError { msg: e.to_string() })?;
    println!("{}", ddc::sha256_hex(&data));
    Ok(())
}

fn cmd_render(args: &[String]) -> Result<(), types::IsaError> {
    if args.len() != 1 {
        usage();
    }
    let src = fs::read_to_string(&args[0]).map_err(|e| types::IsaError::IoError {
        msg: e.to_string(),
    })?;
    let out = executor::compile_ty_source(&src, PlatformKind::Stub)?;
    print!("{}", render::disasm_bytes(&out.code));
    Ok(())
}

fn cmd_test(args: &[String]) -> Result<(), types::IsaError> {
    if args.len() != 1 || args[0] != "golden" {
        usage();
    }
    cmd_test_golden()
}

/// Appendix F G00鈥揋05 plus W-selfhost-min G-SM + G-SM-CHAIN through G-SM-CHAIN12 + G-SM-INC + G-SM-DEC + G-SM-JMP + G-SM-CALL + G-SM-JE + G-SM-JCC-ALL + G-SM-IO. Fail-closed on mismatch / missing files.
