fn repo_root() -> Result<std::path::PathBuf, types::IsaError> {
    let manifest = env!("CARGO_MANIFEST_DIR");
    // verifier/ 鈫?yoyo-rust/ 鈫?repo root
    std::path::Path::new(manifest)
        .join("..")
        .join("..")
        .canonicalize()
        .map_err(|e| types::IsaError::IoError {
            msg: format!("resolve repo root: {e}"),
        })
}

fn check_g00(root: &std::path::Path) -> Result<String, String> {
    let ty_path = root.join("yoyo/tests/golden/00_nop_ret.ty");
    let exp_path = root.join("yoyo/tests/golden/expected/00_nop_ret.code.hex");
    if !ty_path.is_file() {
        return Err(format!("missing fixture {}", ty_path.display()));
    }
    if !exp_path.is_file() {
        return Err(format!("missing expected {}", exp_path.display()));
    }
    let expected = load_expected_hex(&exp_path).map_err(|e| e.to_string())?;
    if expected.len() < 2 || expected[0] != 0x90 || *expected.last().unwrap() != 0xC3 {
        return Err("expected pin must be NOP鈥ET (90 —C3)".into());
    }
    let src = fs::read_to_string(&ty_path).map_err(|e| e.to_string())?;
    let out = executor::compile_ty_source(&src, PlatformKind::Stub).map_err(|e| e.to_string())?;
    if out.code != expected {
        return Err(format!(
            "mismatch: got {} want {}",
            hex_encode(&out.code),
            hex_encode(&expected)
        ));
    }
    let pattern = [0x90u8, 0xC3];
    if !out.code.windows(2).any(|w| w == pattern) {
        return Err("missing 90 C3 pattern".into());
    }
    Ok(format!("code={}", hex_encode(&out.code)))
}

