/// W-SM chained8鈥揷hained12: per-peer Rust goldens for the mechanical RAW_BYTE
/// expansion H_12鈥揌_16. Each check reads the canonical source through
/// compile_one_handler, verifies every handler in isolation, concatenates
/// H_05 through the new handler, and also compiles the matching fixture.
fn check_raw_byte_chain_extension(
    root: &std::path::Path,
    chain: u8,
) -> Result<String, String> {
    let fixture_path = root.join(format!("yoyo/tests/golden/selfhost_min_chained{chain}_handlers.ty"));
    let exp_path = root.join(format!("yoyo/tests/golden/expected/selfhost_min_chained{chain}_handlers.code.hex"));
    let canonical_path = root.join("yoyo/projects/yoyo.ty");
    for path in [&fixture_path, &exp_path, &canonical_path] {
        if !path.is_file() {
            return Err(format!("missing {}", path.display()));
        }
    }

    let expected = load_expected_hex(&exp_path).map_err(|e| e.to_string())?;
    let expected_hex: String = (1..=chain as usize)
        .flat_map(|n| ["90".repeat(n), "c3".to_string()])
        .collect();
    if hex_encode(&expected) != expected_hex {
        return Err(format!(
            "expected pin must equal {expected_hex}, got {}",
            hex_encode(&expected)
        ));
    }

    let canonical_src = fs::read_to_string(&canonical_path).map_err(|e| e.to_string())?;
    let mut combined = Vec::new();
    for index in 0x05..=0x04 + chain {
        let out = executor::compile_one_handler(&canonical_src, index as u16, PlatformKind::Stub)
            .map_err(|e| format!("compile_one_handler(H_{index:02X}): {e}"))?;
        let nops = index - 0x04;
        let mut want = vec![0x90; nops as usize];
        want.push(0xC3);
        if out.code != want {
            return Err(format!(
                "M_rust canonical H_{index:02X} mismatch: got {} want {}",
                hex_encode(&out.code),
                hex_encode(&want)
            ));
        }
        combined.extend_from_slice(&out.code);
    }
    if combined != expected {
        return Err(format!(
            "M_rust chained{chain} combined mismatch: got {} want {}",
            hex_encode(&combined),
            hex_encode(&expected)
        ));
    }

    let fixture_src = fs::read_to_string(&fixture_path).map_err(|e| e.to_string())?;
    let fixture = executor::compile_ty_source(&fixture_src, PlatformKind::Stub)
        .map_err(|e| e.to_string())?;
    if fixture.code != expected {
        return Err(format!(
            "chained{chain} fixture mismatch: got {} want {}",
            hex_encode(&fixture.code),
            hex_encode(&expected)
        ));
    }

    Ok(format!(
        "M_rust read yoyo.ty H_05..H_{:02X} and emitted {} ({}B chained{chain}, opcode A0+FF)",
        0x04 + chain,
        hex_encode(&combined),
        combined.len()
    ))
}

fn check_selfhost_min_chained8(root: &std::path::Path) -> Result<String, String> {
    check_raw_byte_chain_extension(root, 8)
}

