/// body-extend-001: Rust-only golden for H_2E `0x62 ADD slot imm`.
/// Pins load_state(0x50) + `add rax, 3` (imm8 path) + store_state(0x50) + ret.
/// Pin: 498b87800200004883c00349898780020000c3 (19B).
/// Mirrors INC/DEC template but exercises the add_imm primitive.
/// 19B (vs INC/DEC's 18B) because add_imm imm8 is 4B vs inc/dec 3B.
fn check_selfhost_min_add_imm(root: &std::path::Path) -> Result<String, String> {
    use crate::assembler::{emit_add_imm, ret};
    let fixture_path = root.join("yoyo/tests/golden/selfhost_min_add_imm.ty");
    let exp_path = root.join("yoyo/tests/golden/expected/selfhost_min_add_imm.code.hex");
    let canonical_path = root.join("yoyo/projects/yoyo.ty");
    for path in [&fixture_path, &exp_path, &canonical_path] {
        if !path.is_file() {
            return Err(format!("missing {}", path.display()));
        }
    }
    let expected = load_expected_hex(&exp_path).map_err(|e| e.to_string())?;
    if expected.len() != 19
        || expected[0..7] != [0x49, 0x8B, 0x87, 0x80, 0x02, 0x00, 0x00]
        || expected[7..11] != [0x48, 0x83, 0xC0, 0x03]
        || expected[11..18] != [0x49, 0x89, 0x87, 0x80, 0x02, 0x00, 0x00]
        || expected[18] != 0xC3
    {
        return Err(format!(
            "expected pin has wrong shape: {}",
            hex_encode(&expected)
        ));
    }

    let fixture_src = fs::read_to_string(&fixture_path).map_err(|e| e.to_string())?;
    let fixture = executor::compile_ty_source(&fixture_src, PlatformKind::Stub)
        .map_err(|e| e.to_string())?;
    if fixture.code != expected {
        return Err(format!(
            "fixture mismatch: got {} want {}",
            hex_encode(&fixture.code),
            hex_encode(&expected)
        ));
    }

    let canonical_src = fs::read_to_string(&canonical_path).map_err(|e| e.to_string())?;
    let compiled = executor::compile_one_handler(&canonical_src, 0x22, PlatformKind::Stub)
        .map_err(|e| e.to_string())?;
    let mut want = emit_add_imm(0x50, 3).map_err(|e| e.to_string())?;
    want.extend(ret());
    if compiled.code != want {
        return Err(format!(
            "M_rust canonical H_22 mismatch: got {} want {}",
            hex_encode(&compiled.code),
            hex_encode(&want)
        ));
    }
    if compiled.code != expected {
        return Err(format!(
            "M_rust canonical H_22 != expected pin: got {} want {}",
            hex_encode(&compiled.code),
            hex_encode(&expected)
        ));
    }
    Ok(format!(
        "M_rust read yoyo.ty H_22 and emitted {} via opcode add_imm+FF",
        hex_encode(&compiled.code)
    ))
}

