fn check_selfhost_min_jmp(root: &std::path::Path) -> Result<String, String> {
    let fixture_path = root.join("yoyo/tests/golden/selfhost_min_jmp.ty");
    let exp_path = root.join("yoyo/tests/golden/expected/selfhost_min_jmp.code.hex");
    let canonical_path = root.join("yoyo/projects/yoyo.ty");
    for path in [&fixture_path, &exp_path, &canonical_path] {
        if !path.is_file() {
            return Err(format!("missing {}", path.display()));
        }
    }
    let expected = load_expected_hex(&exp_path).map_err(|e| e.to_string())?;
    // H_00 (SET S[0x50]=0 + RET) = 18B + H_19 (JMP to H_00 + RET) = 6B → 24B
    // JMP at offset 18: E9 E9 FF FF FF → rel32=-23 → target=0
    if expected.len() != 24 {
        return Err(format!("expected pin must be 24B, got {}B", expected.len()));
    }
    if expected[18] != 0xE9 {
        return Err(format!("expected pin JMP opcode (E9) at offset 18, got {:02X}", expected[18]));
    }
    let rel = i32::from_le_bytes(expected[19..23].try_into().unwrap());
    let target = (18i32 + 5) + rel; // jmp at offset 18, 5B instruction
    if target != 0 {
        return Err(format!("expected JMP target=0, got target={target} (rel32={rel})"));
    }

    // Fixture compile check
    let fixture_src = fs::read_to_string(&fixture_path).map_err(|e| e.to_string())?;
    let fixture = executor::compile_ty_source(&fixture_src, PlatformKind::Stub)
        .map_err(|e| e.to_string())?;
    if fixture.code != expected {
        return Err(format!(
            "fixture mismatch: got {} want {}",
            hex_encode(&fixture.code),
            hex_encode(&expected)
        ));
    }

    // Canonical full compile: verify JMP exists with valid backward rel32
    let canonical_src = fs::read_to_string(&canonical_path).map_err(|e| e.to_string())?;
    let full = executor::compile_ty_source(&canonical_src, PlatformKind::Stub)
        .map_err(|e| e.to_string())?;
    let jmp_idx = match full.code.iter().position(|b| *b == 0xE9) {
        Some(i) => i,
        None => return Err("canonical compile: JMP (E9) missing".into()),
    };
    if jmp_idx + 5 > full.code.len() {
        return Err("canonical compile: JMP truncated".into());
    }
    let rel32 = i32::from_le_bytes(full.code[jmp_idx + 1..jmp_idx + 5].try_into().unwrap());
    let jmp_target = (jmp_idx as i32) + 5 + rel32;
    if jmp_target < 0 || jmp_target as usize >= full.code.len() {
        return Err(format!(
            "canonical compile: JMP rel32={rel32} out of range (target={jmp_target})"
        ));
    }
    // JMP must go backward (rel32 < 0) toward H_00 at the start
    if rel32 >= 0 {
        return Err(format!(
            "canonical compile: JMP rel32={rel32} must be backward (negative)"
        ));
    }
    let ret_after_jmp = full.code[jmp_idx + 5];
    if ret_after_jmp != 0xC3 {
        return Err(format!(
            "canonical compile: byte after JMP must be RET (C3), got {:02X}",
            ret_after_jmp
        ));
    }

    Ok(format!(
        "fixture={} canonical=JMP@{} rel32={} target=0x{:x}",
        hex_encode(&fixture.code),
        jmp_idx,
        rel32,
        jmp_target
    ))
}

/// W-SM control flow: Rust-only golden for H_20 `0x41 CALL hh`.
