    if expected.len() != 76 {
        return Err(format!("expected pin must be 76B, got {}B", expected.len()));
    }
    // JE opcode 0F 84 should be at offset 69 in the fixture
    if expected[69..71] != [0x0F, 0x84] {
        return Err(format!("expected JE (0F 84) at offset 69, got {:02X} {:02X}", expected[69], expected[70]));
    }
    let rel = i32::from_le_bytes(expected[71..75].try_into().unwrap());
    let target = (69i32 + 6) + rel;
    if target != 0 {
        return Err(format!("expected JE target=0, got target={target} (rel32={rel})"));
    }

